/**
 * D!EMONIC: миграция сохранённых настроек.
 *
 * До появления опции «Автопропуск с задержкой» отсчёт запускался для всех категорий
 * с «Пропускать вручную». Чтобы поведение у существующих установок не поменялось,
 * один раз переводим такие категории на DelayedAutoSkip.
 */

import { CategorySelection, CategorySkipOption } from "../types";
import { supportsDelayedAutoSkip } from "./categories";

const MIGRATION_FLAG = "diemonicDelayedSkipMigrated";

interface MigratableConfig {
    categorySelections: CategorySelection[];
}

interface MigratableLocal {
    skipProfiles: Record<string, { categorySelections: CategorySelection[] }>;
}

function convertSelections(selections: CategorySelection[] | undefined): boolean {
    let changed = false;
    for (const selection of selections ?? []) {
        if (selection.option === CategorySkipOption.ManualSkip && supportsDelayedAutoSkip(selection.name)) {
            selection.option = CategorySkipOption.DelayedAutoSkip;
            changed = true;
        }
    }

    return changed;
}

export function migrateDiemonicConfig(config: MigratableConfig, local: MigratableLocal): void {
    const flags = config as unknown as Record<string, unknown>;
    if (flags[MIGRATION_FLAG]) return;
    flags[MIGRATION_FLAG] = true;

    if (convertSelections(config.categorySelections)) {
        // Переприсваивание нужно, чтобы прокси конфига сохранил изменения
        config.categorySelections = config.categorySelections;
    }

    let profilesChanged = false;
    for (const profile of Object.values(local.skipProfiles ?? {})) {
        profilesChanged = convertSelections(profile.categorySelections) || profilesChanged;
    }
    if (profilesChanged) {
        local.skipProfiles = local.skipProfiles;
    }
}
