/**
 * D!EMONIC: категории, для которых в настройках доступен «Автопропуск с задержкой».
 * Файл без зависимостей, чтобы его можно было импортировать из config.ts без циклических импортов.
 */
export function supportsDelayedAutoSkip(category: string): boolean {
    return !category.startsWith("poi_") && category !== "chapter" && category !== "exclusive_access";
}
